for (chunk in genus_chunks) {
  cat("Processing chunk of genera...\n")
  chunk_results <- lapply(chunk, function(genus) {
    calculate_partial_correlation(
      insert_data = insert_data,
      direction = direction,
      thres = thres,
      genus = genus,
      pre_lengths = pre_lengths,
      phe_variable = phe_variable,
      temp_variable = temp_variable
    )
  })
  all_results <- c(all_results, chunk_results)
}
